  'queue.quVerbalConfirm': { 'zh-Hans': '✓ 现场已向顾客口头确认身体状况与健康禁忌（无心脏病、孕期、过敏等）', en: '✓ The guest\'s health status and contraindications were confirmed verbally on site (no cardiac condition, pregnancy or allergies)', ko: '✓ 현장에서 고객의 건강 상태와 금기 사항을 구두로 확인했습니다 (심장 질환, 임신, 알레르기 없음)', es: '✓ Se ha confirmado verbalmente el estado de salud y las contraindicaciones (sin cardiopatía, embarazo ni alergias)', vi: '✓ Đã xác nhận trực tiếp với khách về tình trạng sức khỏe và chống chỉ định (không bệnh tim, không mang thai, không dị ứng)' },
  'queue.quFormSigned': { 'zh-Hans': '✓ 顾客已完成电子健康问卷与知情同意书签署', en: '✓ The guest has completed the digital health form and consent', ko: '✓ 고객이 전자 건강 문진표와 동의서 서명을 완료했습니다', es: '✓ El cliente ha completado el formulario digital y el consentimiento', vi: '✓ Khách đã hoàn tất phiếu khai báo điện tử và bản đồng ý' },
  'queue.quNoSevereContraindications': { 'zh-Hans': '系统已核验无严重身体禁忌', en: 'The system verified there are no serious contraindications', ko: '시스템이 심각한 신체 금기가 없음을 확인했습니다', es: 'El sistema ha verificado que no hay contraindicaciones graves', vi: 'Hệ thống đã xác minh không có chống chỉ định nghiêm trọng' },
  'queue.quCompliantSigned': { 'zh-Hans': '已签署合规', en: 'Signed and compliant', ko: '서명 완료 · 규정 준수', es: 'Firmado y conforme', vi: 'Đã ký, tuân thủ' },
  'queue.quFormNotConfigured': { 'zh-Hans': '本店未配置电子健康问卷', en: 'No digital health form is configured for this shop', ko: '이 매장에는 전자 건강 문진표가 설정되어 있지 않습니다', es: 'Esta tienda no tiene un formulario de salud digital', vi: 'Cửa hàng chưa cấu hình phiếu sức khỏe điện tử' },
  'queue.quFormNotConfiguredDesc': { 'zh-Hans': '入座前请口头确认禁忌与过敏，不要把「未配置」当成「已签署」。', en: 'Confirm contraindications verbally before seating. An unconfigured form is not a signed waiver.', ko: '착석 전에 금기와 알레르기를 구두로 확인하세요. 미설정은 서명 완료가 아닙니다.', es: 'Confirma verbalmente las contraindicaciones antes de sentar. Un formulario no configurado no es un consentimiento firmado.', vi: 'Hãy xác nhận chống chỉ định bằng lời trước khi xếp chỗ. Chưa cấu hình phiếu không có nghĩa là đã ký.' },
