  'queue.quRollbackOperationBadge': { 'zh-Hans': '回退操作', en: 'Rollback operation', ko: '되돌리기 작업', es: 'Operación de retroceso', vi: 'Thao tác hoàn tác' },
  'queue.quRollbackWarnService': { 'zh-Hans': '⚠️ 回退后将重新恢复服务中计时器，并将工位与技师重新置为「服务中」状态。', en: '⚠️ Rolling back restarts the in-service timer and returns the station and therapist to the “in service” state.', ko: '⚠️ 되돌리면 서비스 타이머가 다시 시작되고 스테이션과 관리사가 「서비스 중」 상태로 돌아갑니다.', es: '⚠️ Al retroceder se reinicia el temporizador y el puesto y el terapeuta vuelven al estado «en servicio».', vi: '⚠️ Sau khi hoàn tác, đồng hồ phục vụ sẽ chạy lại và vị trí cùng kỹ thuật viên trở về trạng thái “đang phục vụ”.' },
  'queue.quRollbackWarnWaiting': { 'zh-Hans': '⚠️ 回退后将释放当前指派的技师与包厢工位，并将客户重新置入候客等待队列。', en: '⚠️ Rolling back releases the assigned therapist and station and returns the guest to the waiting queue.', ko: '⚠️ 되돌리면 배정된 관리사와 스테이션이 해제되고 고객이 대기열로 복귀합니다.', es: '⚠️ Al retroceder se liberan el terapeuta y el puesto asignados y el cliente vuelve a la cola de espera.', vi: '⚠️ Sau khi hoàn tác, kỹ thuật viên và vị trí đã phân công sẽ được giải phóng và khách quay lại hàng chờ.' },
  'queue.quRollbackWarnBooked': { 'zh-Hans': '⚠️ 回退后将撤销客户本次到店签到与健康表记录，恢复为「预约待到店」状态。', en: '⚠️ Rolling back cancels the guest\'s check-in and health form record, returning them to the “booked, awaiting arrival” state.', ko: '⚠️ 되돌리면 고객의 체크인과 문진표 기록이 취소되고 「예약 · 방문 대기」 상태로 돌아갑니다.', es: '⚠️ Al retroceder se anula el registro de llegada y el formulario de salud, y el cliente vuelve al estado «reservado, pendiente de llegar».', vi: '⚠️ Sau khi hoàn tác, việc check-in và phiếu sức khỏe của khách sẽ bị hủy, trở về trạng thái “đã đặt, chờ đến”.' },
  'queue.quRollbackAudit': { 'zh-Hans': '⚠️ 本次回退操作将写入门店收银与运营安全审计日志，请务必核实并记录详细原因。', en: '⚠️ This rollback is written to the store\'s till and operations security audit log. Please verify and record a detailed reason.', ko: '⚠️ 이번 되돌림 작업은 매장 결제·운영 보안 감사 로그에 기록됩니다. 반드시 확인하고 상세 사유를 남겨 주세요.', es: '⚠️ Este retroceso se registra en el log de auditoría de caja y operaciones. Verifícalo y anota un motivo detallado.', vi: '⚠️ Thao tác hoàn tác này sẽ được ghi vào nhật ký kiểm toán thu ngân và vận hành của cửa hàng. Vui lòng đối chiếu và ghi rõ lý do.' },
  'queue.quRollbackReasonLabel': { 'zh-Hans': '请选择回退原因分类 *', en: 'Select a rollback reason *', ko: '되돌림 사유 분류를 선택하세요 *', es: 'Selecciona el motivo del retroceso *', vi: 'Vui lòng chọn nhóm lý do hoàn tác *' },
  'queue.quRollbackNoteLabel': { 'zh-Hans': '具体情况备注说明 (记录入系统审计日志)', en: 'Detailed note (written to the system audit log)', ko: '상세 상황 비고 (시스템 감사 로그에 기록)', es: 'Nota detallada (se guarda en el log de auditoría)', vi: 'Ghi chú chi tiết (lưu vào nhật ký kiểm toán hệ thống)' },
